#include <iostream>
#include <vector>
#include <cstring>
#include <queue>
#include <algorithm>
#include <climits>
using namespace std;

const int MAX_DIM = 20;
const int MAX_NODES = 400;
const int MAX_EDGES = 200000;
const int INF_DIST = 199999999;

int board[MAX_DIM][MAX_DIM];
int bfs_dist[MAX_NODES];
int queue_arr[MAX_NODES];
int in_q[MAX_NODES];
int dist_all[MAX_NODES][MAX_NODES];
int grid_size, total_nodes, time_cap;
string input_row;
int zero_pos_r, zero_pos_c;
int dir_r[4] = {0, 0, -1, 1};
int dir_c[4] = {-1, 1, 0, 0};

struct Edge {
    int u, v, f, next;
};

Edge graph_edges[MAX_EDGES];
int edge_front[MAX_NODES];
int num_edges;
int source_vertex, sink_vertex;
vector<int> supply_coords;
vector<int> demand_coords;

inline int node_id(int r, int c) {
    return (r-1)*grid_size + c;
}

bool in_bounds(int r, int c) {
    return r >= 1 && r <= grid_size && c >= 1 && c <= grid_size && board[r][c] != -1;
}

void build_adj_matrix() {
    total_nodes = grid_size * grid_size;
    memset(dist_all, -1, sizeof(dist_all));
    for (int r = 1; r <= grid_size; r++) {
        for (int c = 1; c <= grid_size; c++) {
            if (board[r][c] == -1) continue;
            int u = node_id(r, c);
            dist_all[u][u] = 0;
            for (int k = 0; k < 4; k++) {
                int nr = r + dir_r[k];
                int nc = c + dir_c[k];
                if (in_bounds(nr, nc)) {
                    int v = node_id(nr, nc);
                    dist_all[u][v] = 1;
                }
            }
        }
    }
}

void single_source_shortest_paths() {
    for (int i = 1; i <= total_nodes; ++i) bfs_dist[i] = INF_DIST;
    int fr = 0, rr = 0;
    int start = node_id(zero_pos_r, zero_pos_c);
    bfs_dist[start] = 0;
    queue_arr[rr++] = start;
    while (fr < rr) {
        int cur = queue_arr[fr++];
        for (int nxt = 1; nxt <= total_nodes; ++nxt) {
            if (dist_all[cur][nxt] == 1 && bfs_dist[nxt] > bfs_dist[cur] + 1) {
                bfs_dist[nxt] = bfs_dist[cur] + 1;
                queue_arr[rr++] = nxt;
            }
        }
    }
}

void all_pairs_paths() {
    for (int k = 1; k <= total_nodes; ++k) {
        for (int i = 1; i <= total_nodes; ++i) {
            for (int j = 1; j <= total_nodes; ++j) {
                if (dist_all[i][k] != -1 && dist_all[k][j] != -1) {
                    if (dist_all[i][j] == -1 || dist_all[i][j] > dist_all[i][k] + dist_all[k][j]) {
                        dist_all[i][j] = dist_all[i][k] + dist_all[k][j];
                    }
                }
            }
        }
    }
}

void setup_flow_network() {
    memset(edge_front, -1, sizeof(edge_front));
    num_edges = 0;
    source_vertex = 0;
    sink_vertex = supply_coords.size() / 3 + demand_coords.size() / 3 + 1;

    for (size_t i = 0; i < supply_coords.size(); i += 3) {
        int cnt = supply_coords[i+2];
        graph_edges[num_edges] = {source_vertex, (int)(i/3)+1, cnt, edge_front[source_vertex]};
        edge_front[source_vertex] = num_edges++;
        graph_edges[num_edges] = {(int)(i/3)+1, source_vertex, 0, edge_front[(int)(i/3)+1]};
        edge_front[(int)(i/3)+1] = num_edges++;
    }

    for (size_t i = 0; i < demand_coords.size(); i += 3) {
        int cnt = demand_coords[i+2];
        graph_edges[num_edges] = {(int)(supply_coords.size()/3) + (int)(i/3)+1, sink_vertex, cnt, edge_front[(int)(supply_coords.size()/3) + (int)(i/3)+1]};
        edge_front[(int)(supply_coords.size()/3) + (int)(i/3)+1] = num_edges++;
        graph_edges[num_edges] = {sink_vertex, (int)(supply_coords.size()/3) + (int)(i/3)+1, 0, edge_front[sink_vertex]};
        edge_front[sink_vertex] = num_edges++;
    }

    int source_node_id = node_id(zero_pos_r, zero_pos_c);
    for (size_t i = 0; i < supply_coords.size(); i += 3) {
        int sr = supply_coords[i], sc = supply_coords[i+1];
        int sp = node_id(sr, sc);
        for (size_t j = 0; j < demand_coords.size(); j += 3) {
            int dr = demand_coords[j], dc = demand_coords[j+1];
            int dp = node_id(dr, dc);
            if (dist_all[sp][dp] != -1 && dist_all[sp][dp] <= time_cap) {
                if (dist_all[sp][dp] < bfs_dist[dp]) {
                    graph_edges[num_edges] = {(int)(i/3)+1, (int)(supply_coords.size()/3) + (int)(j/3)+1, INF_DIST, edge_front[(int)(i/3)+1]};
                    edge_front[(int)(i/3)+1] = num_edges++;
                    graph_edges[num_edges] = {(int)(supply_coords.size()/3) + (int)(j/3)+1, (int)(i/3)+1, 0, edge_front[(int)(supply_coords.size()/3) + (int)(j/3)+1]};
                    edge_front[(int)(supply_coords.size()/3) + (int)(j/3)+1] = num_edges++;
                } else if (dist_all[sp][dp] == bfs_dist[dp]) {
                    for (int d = 0; d < 4; ++d) {
                        int nr = dr + dir_r[d], nc = dc + dir_c[d];
                        if (in_bounds(nr, nc)) {
                            int np = node_id(nr, nc);
                            if (dist_all[sp][np] == dist_all[sp][dp] - 1 && dist_all[sp][np] < bfs_dist[np]) {
                                graph_edges[num_edges] = {(int)(i/3)+1, (int)(supply_coords.size()/3) + (int)(j/3)+1, INF_DIST, edge_front[(int)(i/3)+1]};
                                edge_front[(int)(i/3)+1] = num_edges++;
                                graph_edges[num_edges] = {(int)(supply_coords.size()/3) + (int)(j/3)+1, (int)(i/3)+1, 0, edge_front[(int)(supply_coords.size()/3) + (int)(j/3)+1]};
                                edge_front[(int)(supply_coords.size()/3) + (int)(j/3)+1] = num_edges++;
                            }
                        }
                    }
                }
            }
        }
    }
}

int node_level[MAX_NODES];
int bfs_queue[MAX_NODES];

bool level_graph_bfs() {
    memset(node_level, -1, sizeof(node_level));
    int f = 0, r = 0;
    bfs_queue[r++] = source_vertex;
    node_level[source_vertex] = 0;
    while (f < r) {
        int u = bfs_queue[f++];
        for (int e = edge_front[u]; ~e; e = graph_edges[e].next) {
            int v = graph_edges[e].to;
            if (node_level[v] == -1 && graph_edges[e].flow > 0) {
                node_level[v] = node_level[u] + 1;
                if (v == sink_vertex) return true;
                bfs_queue[r++] = v;
            }
        }
    }
    return false;
}

int stack_path[MAX_NODES];
int curr_edge[MAX_NODES];

int dinic_dfs(int u, int min_flow) {
    if (u == sink_vertex) return min_flow;
    for (int &i = curr_edge[u]; ~i; i = graph_edges[i].next) {
        int v = graph_edges[i].to;
        if (node_level[v] == node_level[u] + 1 && graph_edges[i].flow > 0) {
            int pushed = dinic_dfs(v, min(min_flow, graph_edges[i].flow));
            if (pushed > 0) {
                graph_edges[i].flow -= pushed;
                graph_edges[i^1].flow += pushed;
                return pushed;
            }
        }
    }
    return 0;
}

int compute_max_flow() {
    int total = 0;
    while (level_graph_bfs()) {
        for (int i = 0; i <= sink_vertex; ++i) curr_edge[i] = edge_front[i];
        while (int pushed = dinic_dfs(source_vertex, INF_DIST)) {
            total += pushed;
        }
    }
    return total;
}

int main_solution() {
    board[zero_pos_r][zero_pos_c] = 0;
    build_adj_matrix();
    single_source_shortest_paths();
    board[zero_pos_r][zero_pos_c] = -1;
    build_adj_matrix();
    all_pairs_paths();
    setup_flow_network();
    return compute_max_flow();
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    cin >> grid_size >> time_cap;
    supply_coords.clear();
    demand_coords.clear();
    memset(board, 0, sizeof(board));

    for (int i = 1; i <= grid_size; ++i) {
        cin >> input_row;
        for (int j = 0; j < grid_size; ++j) {
            if (input_row[j] == 'Y') board[i][j+1] = -1;
            else if (input_row[j] == 'Z') {
                zero_pos_r = i; zero_pos_c = j+1;
                board[i][j+1] = -1;
            }
            else if (input_row[j] > '0' && input_row[j] <= '9') {
                supply_coords.push_back(i);
                supply_coords.push_back(j+1);
                supply_coords.push_back(input_row[j]-'0');
            }
        }
    }

    for (int i = 1; i <= grid_size; ++i) {
        cin >> input_row;
        for (int j = 0; j < grid_size; ++j) {
            if (input_row[j] > '0' && input_row[j] <= '9') {
                demand_coords.push_back(i);
                demand_coords.push_back(j+1);
                demand_coords.push_back(input_row[j]-'0');
            }
        }
    }

    cout << main_solution() << '\n';
    return 0;
}
